class Solution {
    public int countNegatives(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int row = rows - 1;
        int col = 0;
        int count = 0;

        while (row >= 0 && col < cols) {
            if (grid[row][col] < 0) {
                count += cols - col;
                row--;
            } else {
                col++;
            }
        }
        return count;
    }
}

class Solution {
    public int countNegatives(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int firstNegative = cols;
        int count = 0;

        for (int row = 0; row < rows; row++) {
            while (firstNegative > 0 && grid[row][firstNegative - 1] < 0) {
                firstNegative--;
            }
            count += cols - firstNegative;
        }
        return count;
    }
}

class Solution {
    public int countNegatives(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int row = 0; row < rows; row++) {
            int left = 0;
            int right = cols;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (grid[row][mid] < 0) {
                    right = mid;
                } else {
                    left = mid + 1;
                }
            }
            count += cols - left;
        }
        return count;
    }
}

class Solution {
    public int countNegatives(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int col = 0; col < cols; col++) {
            int low = 0;
            int high = rows - 1;
            int first = rows;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                if (grid[mid][col] < 0) {
                    first = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            count += rows - first;
        }
        return count;
    }
}

